# chain over j (r1, t): fused into 2 states (r1, t); selection: original
# Merge operands must represent non-empty parts; execution skips empty partitions.
def merge_j(a, b):
    t0 = tir.max(a[0], b[0])
    return (
        t0,  # r1
        (((tir.exp((-(t0 - a[0])))) * a[1]) + ((tir.exp((-(t0 - b[0])))) * b[1])),  # t
    )

j = te.reduce_axis((1, m), name="j")

def compute_j(i):
    # TE's initialization hook holds the first leaf, not an empty state.
    def identity_j(t0, t1):
        return (
            c1[i, 0],  # r1
            (tir.const(0.125, "float32") * (tir.exp((tir.const(-0.5, "float32") * c2[i, 0])))),  # t
        )
    fused_j = te.comm_reducer(merge_j, identity_j, name="fused_j")
    return fused_j(
        (
            c1[i, j],  # r1
            (tir.const(0.125, "float32") * (tir.exp((tir.const(-0.5, "float32") * c2[i, j])))),  # t
        ),
        axis=j,
    )

r1, t = te.compute(
    (n,), compute_j,
    name="fused_r1_t",
    tag="superopt.nonempty",
)
r1, t = te.compute(
